{"version":"0.29.2","publicada":"2026-11-12T17:06:45.126Z","notas":"Community nodes now also update their compose file and their own updater.","servicios":{"consola":"ghcr.io/seguridadsi/sugardaddy-consola:0.29.2@sha256:45404897308247329b5514b4f2d24d3ef8006afeb638bd0f3abd6e73fcee5d4a","sensor":"ghcr.io/seguridadsi/sugardaddy-sensor:0.29.2@sha256:9efca612d2bbeaa41e7168f06a200c3397dbd60ff985f8b9f893c9d51f9b6a64"},"actualizador":"ghcr.io/seguridadsi/sugardaddy-actualizador:0.29.2@sha256:f76e38accaae8f70621b4673a4fe7d92e1f6172e17a6be77c7186736c655b830","nodo":{"ficheros":{"compose.yml":"# Nodo de Sugardaddy en casa del cliente. Lo arranca instalar.sh:
#   docker compose --env-file .env --env-file versiones.env up -d
#
# versiones.env (qué imagen lleva cada servicio) lo reescribe el actualizador
# tras cada versión instalada; .env (secretos y ajustes) lo genera instalar.sh.
name: sugardaddy

x-endurecido: &endurecido
  read_only: true
  cap_drop: [ALL]
  security_opt: [no-new-privileges:true]
  restart: unless-stopped
  # Registros de Docker con tope: por defecto crecen sin fin en la máquina del cliente.
  logging:
    driver: json-file
    options: { max-size: 10m, max-file: '3' }

services:
  postgres:
    <<: *endurecido
    image: postgres:17-alpine@sha256:b0f9560a2de083e2cc7382e75f808c7381a32852a7ec49117deedb300e552b24
    # Postgres necesita algunas capacidades para cambiar al usuario postgres al arrancar.
    cap_drop: []
    environment:
      POSTGRES_USER: sugardaddy
      POSTGRES_PASSWORD: ${POSTGRES_PASSWORD:?falta en .env}
      POSTGRES_DB: consola
    volumes:
      - datos-postgres:/var/lib/postgresql/data
    tmpfs: [/tmp, /var/run/postgresql]
    networks: [interna]
    healthcheck:
      test: ['CMD-SHELL', 'pg_isready -U sugardaddy -d consola']
      interval: 5s
      retries: 20

  consola:
    <<: *endurecido
    image: ${CONSOLA_IMAGEN:?falta en versiones.env}
    depends_on:
      postgres: { condition: service_healthy }
    environment:
      DATABASE_URL: postgres://sugardaddy:${POSTGRES_PASSWORD}@postgres:5432/consola
      # Modo FIJO: ORIGIN es la URL del nodo. Modo «cualquier IP/nombre»: ORIGIN
      # vacío y el origen se saca de las cabeceras que pone Caddy (así vale por
      # cualquier host). Lo decide instalar.sh. Por defecto (nodo de antes), la URL.
      ORIGIN: ${ORIGIN-${CONSOLA_URL}}
      # El nombre propio de la consola, también en modo «cualquier IP/nombre»:
      # es la dirección que se da a los sensores remotos para que la llamen.
      CONSOLA_URL: ${CONSOLA_URL:-}
      PROTOCOL_HEADER: ${PROTOCOL_HEADER:-}
      HOST_HEADER: ${HOST_HEADER:-}
      # La IP del navegador es la que pone Caddy, el único que llega a la
      # consola, al final de X-Forwarded-For («Probar» la propone).
      ADDRESS_HEADER: X-Forwarded-For
      XFF_DEPTH: '1'
      # Acceso a la consola por IP (docs/diseno/acceso-consola.md): la lista que
      # dio quien instaló, si la dio, y la IP de su sesión SSH como propuesta.
      # NODO_DIR, para decir dónde está el fichero de emergencia (abrir-consola).
      CONSOLA_ACCESO: ${CONSOLA_ACCESO:-}
      CONSOLA_ACCESO_PROPUESTA: ${CONSOLA_ACCESO_PROPUESTA:-}
      NODO_DIR: ${NODO_DIR:-}
      NODO_ID: ${NODO_ID:?falta en .env}
      NODO_NOMBRE: ${NODO_NOMBRE:?falta en .env}
      SENSOR_LOCAL_TOKEN: ${SENSOR_LOCAL_TOKEN}
      # La red y la VLAN de esta máquina, para el sensor local en Sensores (las
      # detecta instalar.sh; vacías, se indican a mano en la consola).
      SENSOR_LOCAL_RED: ${SENSOR_LOCAL_RED:-}
      SENSOR_LOCAL_VLAN: ${SENSOR_LOCAL_VLAN:-}
      ACTUALIZADOR_TOKEN: ${ACTUALIZADOR_TOKEN}
      # Las claves de publicación en las que se confía, por uso, y la de legado
      # (docs/diseno/claves-y-catalogo.md): las renueva una versión firmada.
      PUBLICACION_CLAVES: ${PUBLICACION_CLAVES:-}
      PUBLICACION_CLAVE_PUBLICA: ${PUBLICACION_CLAVE_PUBLICA:-}
      # Cifra los secretos que el cliente pone en su consola (avisos y SIEM).
      # La generan instalar.sh y, en un nodo de antes, el actualizador
      # (entorno.json); vacía, la consola no guarda secretos.
      CLAVE_SECRETOS: ${CLAVE_SECRETOS:-}
      ENTRA_TENANT_ID: ${ENTRA_TENANT_ID:-}
      ENTRA_CLIENT_ID: ${ENTRA_CLIENT_ID:-}
      ENTRA_CLIENT_SECRET: ${ENTRA_CLIENT_SECRET:-}
      ENTRA_GRUPO_CLIENTE: ${ENTRA_GRUPO_CLIENTE:-}
      ENTRA_GRUPO_SOPORTE: ${ENTRA_GRUPO_SOPORTE:-}
      # Login local: entrar con usuario y contraseña del propio nodo, como
      # alternativa (o complemento) a Entra. En la edición community va activo;
      # en un nodo federado se deja vacío. Ver docs/diseno/auth-login.md.
      LOGIN_LOCAL: ${LOGIN_LOCAL:-}
      EDICION: ${EDICION:-}
      # Trampas de partner (docs/diseno/trampas-de-partner.md): solo acepta el catálogo
      # de este partner, y se lo dice a los sensores que instala en otras máquinas.
      PARTNER: ${PARTNER:-}
      REGISTRO_PARTNER: ${REGISTRO_PARTNER:-}
      REGISTRO_PARTNER_USUARIO: ${REGISTRO_PARTNER_USUARIO:-}
      REGISTRO_PARTNER_TOKEN: ${REGISTRO_PARTNER_TOKEN:-}
      PANEL_HTTP_PERMITIDO: ${PANEL_HTTP_PERMITIDO:-}
      # Alta automática en el panel la primera vez (la deja el instalador).
      PANEL_URL: ${PANEL_URL:-}
      PANEL_ALTA_CODIGO: ${PANEL_ALTA_CODIGO:-}
      # Para las líneas de instalación de sensores en otras máquinas: estos
      # tienen que confiar en el HTTPS de la consola.
      TLS_MODO: ${TLS_MODO:-interno}
      CA_RAIZ: /ca/ca-raiz.crt
    volumes:
      # La raíz (pública) de la CA del nodo, que copia ahí el instalador o el
      # auxiliar: la carpeta de Caddy solo la lee root y nunca entra aquí.
      - ./ca-raiz.crt:/ca/ca-raiz.crt:ro
    tmpfs: [/tmp]
    # Sin puertos propios: se entra por https, a través de Caddy.
    # Puede salir a internet: es la que habla con el panel central y con las
    # herramientas del cliente (su SIEM, su correo…).
    networks: [interna, nodo]
    labels:
      sugardaddy.servicio: consola
      sugardaddy.salud: http://consola:3000/api/salud
    # Lo que espera compose (up --wait) al aplicar una versión: que responda de verdad.
    healthcheck:
      test:
        [
          'CMD',
          'node',
          '-e',
          "fetch('http://localhost:3000/api/salud').then((r) => process.exit(r.ok ? 0 : 1), () => process.exit(1))"
        ]
      interval: 5s
      timeout: 4s
      retries: 30
      start_period: 20s

  https:
    <<: *endurecido
    image: caddy:2-alpine@sha256:d8542f48d34a9cf4e4c11a478865229840e87e4c96ea3f439101f31a5d35f75f
    depends_on: [consola]
    # Escuchar en el 443 necesita esta capacidad, y ninguna más.
    cap_add: [NET_BIND_SERVICE]
    environment:
      CONSOLA_DOMINIO: ${CONSOLA_DOMINIO:?falta en .env}
      TLS_MODO: ${TLS_MODO:-interno}
      # Modo de entrada, para elegir el sitio del Caddyfile. «Cualquier IP o
      # nombre» lo marca HOST_HEADER, que instalar.sh solo pone en ese modo (la
      # consola saca entonces el origen de las cabeceras de Caddy); vacío = fijo.
      CADDY_MODO: ${HOST_HEADER:+-cualquier-ip}
      # La CA con la que firma (docs/diseno/ca-nodo.md): «nodo», la propia, en
      # ca-nodo/; vacío (nodo instalado antes que ella), la de Caddy, «local».
      CADDY_CA: ${CA_NODO:-local}
    ports:
      - '${CONSOLA_ESCUCHA:-0.0.0.0}:${CONSOLA_PUERTO:-443}:443'
    volumes:
      - ./Caddyfile:/etc/caddy/Caddyfile:ro
      - ./certs:/certs:ro
      # La raíz, la intermedia y su clave. Solo Caddy la monta: la consola
      # recibe la raíz (pública) en ca-raiz.crt.
      - ./ca-nodo:/ca-nodo:ro
      - datos-caddy:/data
    tmpfs: [/config]
    networks: [nodo]

  sensor:
    <<: *endurecido
    image: ${SENSOR_IMAGEN:?falta en versiones.env}
    depends_on: [consola]
    # Para liberar lo ya leído de los registros de las trampas, que escribe el
    # usuario de cada honeypot y no el del sensor; si no, el tope de disco de
    # cada trampa no funciona. Con el socket de Docker ya equivale a root.
    cap_add: [DAC_OVERRIDE]
    command:
      - -consola=http://consola:3000
      - -datos=${DATOS:?falta en .env}/sensor
      - -escucha=${TRAMPAS_ESCUCHA:-0.0.0.0}
      - -desplazar=${TRAMPAS_DESPLAZAR:-0}
      - -salud=:9100
      # La versión firmada instalada: su catálogo es lo único que se arranca (SEN-3).
      - -firmado=/firmado/version.json
    environment:
      SUGARDADDY_TOKEN: ${SENSOR_LOCAL_TOKEN}
      # Con ellas comprueba la firma de esa versión, que tiene que ser de su edición.
      EDICION: ${EDICION:-}
      PUBLICACION_CLAVES: ${PUBLICACION_CLAVES:-}
      PUBLICACION_CLAVE_PUBLICA: ${PUBLICACION_CLAVE_PUBLICA:-}
      # Con su propia imagen comprueba que las trampas no se ven entre sí.
      SENSOR_IMAGEN: ${SENSOR_IMAGEN}
      # Con la del actualizador lanza el auxiliar que monta el disco de tamaño
      # fijo de cada trampa (docs/diseno/discos-trampa.md).
      ACTUALIZADOR_IMAGEN: ${ACTUALIZADOR_IMAGEN}
      # Las imágenes de las trampas propias están en el registro privado (solo lectura).
      REGISTRO: ${REGISTRO:-ghcr.io}
      REGISTRO_USUARIO: ${REGISTRO_USUARIO:-}
      REGISTRO_TOKEN: ${REGISTRO_TOKEN:-}
      # Trampas de partner (docs/diseno/trampas-de-partner.md): de qué partner es este
      # nodo y de dónde descarga sus imágenes. Vacío: no arranca trampas de partner.
      PARTNER: ${PARTNER:-}
      REGISTRO_PARTNER: ${REGISTRO_PARTNER:-}
      REGISTRO_PARTNER_USUARIO: ${REGISTRO_PARTNER_USUARIO:-}
      REGISTRO_PARTNER_TOKEN: ${REGISTRO_PARTNER_TOKEN:-}
    volumes:
      - /var/run/docker.sock:/var/run/docker.sock
      # Misma ruta dentro y fuera: el sensor monta en las trampas carpetas
      # que el motor de Docker tiene que encontrar en el anfitrión. Con
      # propagación (rslave) ve los discos de las trampas que su auxiliar monta
      # después de que arranque (docs/diseno/discos-trampa.md). Solo si la
      # máquina la admite: lo prueban el instalador y el auxiliar de cada
      # versión, que dejan SENSOR_PROPAGACION en .env; si no, Docker no
      # arrancaría el sensor (un contenedor LXC con la raíz privada).
      - type: bind
        source: ${DATOS}/sensor
        target: ${DATOS}/sensor
        bind:
          propagation: ${SENSOR_PROPAGACION:-rprivate}
          create_host_path: true
      # La deja el actualizador; una carpeta y no el fichero, que se reescribe con un rename.
      - ${NODO_DIR}/firmado:/firmado:ro
    networks: [nodo]
    labels:
      sugardaddy.servicio: sensor
      sugardaddy.salud: http://sensor:9100/salud
    healthcheck:
      test: ['CMD', '/app', 'salud', 'http://localhost:9100/salud']
      interval: 5s
      timeout: 4s
      retries: 30
      start_period: 30s

  actualizador:
    <<: *endurecido
    # En versiones.env: las versiones firmadas también cambian el actualizador.
    image: ${ACTUALIZADOR_IMAGEN:?falta en versiones.env}
    depends_on: [consola]
    command:
      - -consola=http://consola:3000
      - -versiones=/nodo/versiones.env
      - -salud=:9101
    environment:
      ACTUALIZADOR_TOKEN: ${ACTUALIZADOR_TOKEN}
      # La carpeta del nodo vista desde el anfitrión: la necesita el auxiliar
      # que aplica la configuración, que la monta en la misma ruta.
      NODO_DIR: ${NODO_DIR}
      # Su edición: solo acepta versiones de ella (Community o Cloud).
      EDICION: ${EDICION:-}
      PUBLICACION_CLAVES: ${PUBLICACION_CLAVES:-}
      PUBLICACION_CLAVE_PUBLICA: ${PUBLICACION_CLAVE_PUBLICA:-}
      # Para descargar las versiones nuevas de un registro privado (solo lectura).
      REGISTRO: ${REGISTRO:-ghcr.io}
      REGISTRO_USUARIO: ${REGISTRO_USUARIO:-}
      REGISTRO_TOKEN: ${REGISTRO_TOKEN:-}
      # Con PARTNER trae de la consola el catálogo de trampas de ese partner, lo
      # comprueba y lo deja para el sensor (docs/diseno/trampas-de-partner.md).
      PARTNER: ${PARTNER:-}
    volumes:
      - /var/run/docker.sock:/var/run/docker.sock
      - ${NODO_DIR:?falta en .env}:/nodo
    networks: [nodo]
    labels:
      sugardaddy.servicio: actualizador
    healthcheck:
      test: ['CMD', '/app', 'salud', 'http://localhost:9101/salud']
      interval: 5s
      timeout: 4s
      retries: 12

networks:
  # Postgres solo es visible para la consola, y esta red no sale a internet.
  interna:
    internal: true
  nodo: {}

volumes:
  datos-postgres: {}
  # Los certificados que emite Caddy y, en un nodo instalado antes de la CA
  # propia (docs/diseno/ca-nodo.md), la CA de Caddy, que se destruye al pasar
  # a la propia. Si se pierde esa CA, hay que volver a repartir su raíz.
  datos-caddy: {}
","Caddyfile":"# Entrada HTTPS de la consola del nodo. Lo único del nodo que escucha hacia la
# red del cliente, junto con las trampas.
#
# Un solo fichero para los dos modos de entrada: viaja firmado con cada versión
# y el actualizador lo escribe tal cual, así que el modo no puede vivir aquí.
# Vive en .env y compose.yml lo pasa en CADDY_MODO, que elige el sitio de abajo:
#  - Fijo (por defecto): solo la dirección dada al instalar.
#  - «Cualquier IP o nombre» (ENTRAR_CUALQUIER_IP=1 al instalar): :443 para
#    cualquier host, con certificado a demanda. Con la CA de Caddy de antes,
#    en un nodo con IP pública Caddy puede emitir certificados a quien se los
#    pida (riesgo menor; por eso NO es el modo por defecto); con la CA propia,
#    solo para la dirección de la consola (ask, abajo).
#
# La CA con la que firma Caddy en TLS_MODO=interno (docs/diseno/ca-nodo.md) la
# elige CA_NODO de .env, que compose pasa en CADDY_CA:
#  - «nodo»: la CA propia del nodo, en ca-nodo/. Su raíz solo vale para la
#    dirección de la consola; Caddy firma con la intermedia y no tiene la clave
#    de la raíz.
#  - «local» (nodos instalados antes): la CA que Caddy crea en su volumen, sin
#    límite de nombres, hasta que el administrador pasa a la propia desde la
#    consola.
# Los fragmentos que elige tienen que estar antes del bloque global.
(ca-local) {
}

(ca-nodo) {
	pki {
		ca nodo {
			name "Sugardaddy node"
			root {
				cert /ca-nodo/raiz.crt
			}
			intermediate {
				cert /ca-nodo/intermedia.crt
				key /ca-nodo/intermedia.key
			}
		}
	}
	# Modo «cualquier IP o nombre»: Caddy solo pide certificado a demanda para
	# la dirección de la consola, la única que permite la raíz. Contesta el
	# sitio del 127.0.0.1 de abajo, dentro de este mismo contenedor.
	on_demand_tls {
		ask http://127.0.0.1:5555/permiso
	}
}

{
	admin off
	# Sin peticiones a Let's Encrypt ni a ningún sitio: el nodo no sale a
	# buscar certificados.
	auto_https disable_redirects
	skip_install_trust
	# Al entrar por IP el navegador no manda SNI; para una IP (sobre todo pública)
	# Caddy no sabría qué certificado presentar y abortaría el TLS (internal error).
	# Con esto usa el de la dirección del nodo cuando no hay SNI, así se entra por IP.
	default_sni {$CONSOLA_DOMINIO}
	import ca-{$CADDY_CA}
}

(tls-interno) {
	# CA del nodo (la elegida arriba). Su raíz la dejan en ca-raiz.crt
	# instalar.sh o el actualizador, para instalarla en los equipos que entren
	# a la consola.
	tls {
		issuer internal {
			ca {$CADDY_CA}
		}
	}
}

(tls-interno-a-demanda) {
	# Igual, pero emite el certificado del host con que te conectes (sin esto,
	# en :443 un SNI nuevo rompería el TLS). Sin SNI (al entrar por IP), el de
	# default_sni.
	tls {
		issuer internal {
			ca {$CADDY_CA}
		}
		on_demand
	}
}

(tls-ficheros) {
	# Certificado de la CA del cliente, dejado en certs/ por quien instala.
	tls /certs/certificado.pem /certs/clave.pem
}

(tls-ficheros-a-demanda) {
	# Con certificado propio no se emite nada: el mismo para cualquier host.
	tls /certs/certificado.pem /certs/clave.pem
}

(consola) {
	encode zstd gzip
	header {
		Strict-Transport-Security "max-age=31536000"
		-Server
	}
	reverse_proxy consola:3000
}

# Modo fijo (CADDY_MODO vacío).
(sitio) {
	{$CONSOLA_DOMINIO}:443 {
		import tls-{$TLS_MODO}
		import consola
	}
}

# Modo «cualquier IP o nombre» (CADDY_MODO=-cualquier-ip).
(sitio-cualquier-ip) {
	:443 {
		import tls-{$TLS_MODO}-a-demanda
		import consola
	}
	# El «ask» de la CA propia: sí solo a la dirección de la consola. Solo en
	# el bucle local del contenedor; con la CA de antes nadie lo pregunta.
	http://127.0.0.1:5555 {
		bind 127.0.0.1
		@consola query domain={$CONSOLA_DOMINIO}
		respond @consola 200
		respond 403
	}
}

import sitio{$CADDY_MODO}
